from pyquest import *

def inside(px, py, x, y, w, h):
    return px >= x and px <= x + w and py >= y and py <= y + h


draw_rect(100, 200, 200, 150, "lightgray")
for i in range(8):
    px = i * 50 + 20
    if inside(px, 270, 100, 200, 200, 150):
        draw_rect(px, 270, 10, 10, "red")
    else:
        draw_rect(px, 270, 10, 10, "black")

from pyquest import *

def bigger(a, b):
    if a > b:
        return a
    else:
        return b


h = bigger(120, 260)
draw_rect(180, 550 - h, 40, h, "orange")
